<?php require_once __DIR__.'/../includes/tutor_auth_check.php';require_once __DIR__.'/../config/db.php';$rows=[];try{$p=db();$q=$p->prepare('SELECT id FROM tutors WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$tid=(int)$q->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){$bid=(int)$_POST['booking_id'];$status=$_POST['action']==='accept'?'accepted':'rejected';$q=$p->prepare("UPDATE bookings SET status=? WHERE id=? AND tutor_id=? AND status='pending'");$q->execute([$status,$bid,$tid]);$q=$p->prepare("INSERT INTO notifications(user_id,type,message,related_id) SELECT student_id,?, ?,id FROM bookings WHERE id=? AND tutor_id=?");$q->execute([$status==='accepted'?'booking_accepted':'booking_rejected',$status==='accepted'?'Your booking was accepted.':'Your booking was rejected.',$bid,$tid]);}$q=$p->prepare("SELECT b.*,u.full_name student,s.name subject FROM bookings b JOIN users u ON u.id=b.student_id JOIN subjects s ON s.id=b.subject_id WHERE b.tutor_id=? AND b.status='pending' ORDER BY b.created_at");$q->execute([$tid]);$rows=$q->fetchAll();}catch(Throwable $e){}$pageTitle='Booking requests';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="container py-5"><h1 class="h2">Booking requests</h1><?php foreach($rows as $r):?><div class="profile-section mb-3"><strong><?=e($r['student'])?></strong> requested <?=e($r['subject'])?> on <?=e($r['booking_date'])?><form method="post" class="float-end"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$r['id']?>"><button class="btn btn-success btn-sm" name="action" value="accept">Accept</button><button class="btn btn-outline-danger btn-sm" name="action" value="reject">Reject</button></form></div><?php endforeach;if(!$rows):?><p class="text-secondary">No pending requests.</p><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
